// Provenance: all vectors here are SYNTHETIC (generated by this package's
// own encoder) except the CCSDS PN prefix and ASM constant, which are
// published spec values.

func TestCCSDSPNPrefix(t *testing.T) {
	want := []byte{0xFF, 0x48, 0x0E, 0xC0, 0x9A, 0x0D, 0x70, 0xBC}
	if got := ccsdsPN(8); !bytes.Equal(got, want) {
		t.Fatalf("pn %x want %x", got, want)
	}
}

func TestG3RUHRoundTrip(t *testing.T) {
	r := rand.New(rand.NewSource(1))
	in := make([]bool, 500)
	for i := range in {
		in[i] = r.Intn(2) == 1
	}
	out := G3RUHDescramble(G3RUHScramble(in))
	for i := range in {
		if in[i] != out[i] {
			t.Fatalf("mismatch at %d", i)
		}
	}
	// Self-sync: a descrambler started mid-stream recovers after 17 bits.
	sc := G3RUHScramble(in)
	o2 := G3RUHDescramble(sc[100:])
	for i := 17; i < len(o2); i++ {
		if o2[i] != in[100+i] {
			t.Fatalf("no self-sync at %d", i)
		}
	}
}

func TestRSCorrects(t *testing.T) {
	r := rand.New(rand.NewSource(2))
	data := make([]byte, 223)
	r.Read(data)
	cw := RSEncode(data)
	if _, err := RSDecode(append([]byte{}, cw...)); err != nil {
		t.Fatal(err)
	}
	for _, nerr := range []int{1, 5, 16} {
		bad := append([]byte{}, cw...)
		for _, p := range r.Perm(255)[:nerr] {
			bad[p] ^= byte(1 + r.Intn(255))
		}
		n, err := RSDecode(bad)
		if err != nil || n != nerr || !bytes.Equal(bad, cw) {
			t.Fatalf("nerr=%d got n=%d err=%v", nerr, n, err)
		}
	}
	bad := append([]byte{}, cw...)
	for _, p := range r.Perm(255)[:17] {
		bad[p] ^= 0x5A
	}
	if _, err := RSDecode(bad); err == nil {
		// 17 errors may rarely miscorrect; must at least not equal original.
		if bytes.Equal(bad, cw) {
			t.Fatal("impossible")
		}
	}
	// Shortened code.
	sd := data[:100]
	scw := RSEncode(sd)
	scw[3] ^= 0xFF
	scw[120] ^= 0x01
	if n, err := RSDecode(scw); err != nil || n != 2 || !bytes.Equal(scw[:100], sd) {
		t.Fatalf("short n=%d err=%v", n, err)
	}
}

func bitsOf(b []byte) []bool {
	var o []bool
	for _, x := range b {
		for i := 7; i >= 0; i-- {
			o = append(o, x>>uint(i)&1 == 1)
		}
	}
	return o
}

func buildStream(frames [][]byte, interleave int, junk int, invert bool, flips int, r *rand.Rand) []bool {
	var bits []bool
	for i := 0; i < junk; i++ {
		bits = append(bits, r.Intn(2) == 1)
	}
	for _, d := range frames {
		per := len(d) / interleave
		cws := make([][]byte, interleave)
		for i := range cws {
			blk := make([]byte, per)
			for j := range blk {
				blk[j] = d[j*interleave+i]
			}
			cws[i] = RSEncode(blk)
		}
		// byte-interleave
		raw := make([]byte, 0, (per+32)*interleave)
		for j := 0; j < per+32; j++ {
			for i := 0; i < interleave; i++ {
				raw = append(raw, cws[i][j])
			}
		}
		CCSDSDerandomize(raw) // XOR is symmetric
		bits = append(bits, bitsOf([]byte{0x1A, 0xCF, 0xFC, 0x1D})...)
		bits = append(bits, bitsOf(raw)...)
	}
	for i := 0; i < flips; i++ {
		p := junk + 32 + r.Intn(len(frames[0])*8)
		bits[p] = !bits[p]
	}
	if invert {
		for i := range bits {
			bits[i] = !bits[i]
		}
	}
	return bits
}

func TestCCSDSDeframe(t *testing.T) {
	r := rand.New(rand.NewSource(3))
	for _, tc := range []struct {
		il, flips int
		inv       bool
	}{{1, 0, false}, {1, 12, false}, {1, 10, true}, {4, 16, false}} {
		d := make([]byte, 223*tc.il)
		r.Read(d)
		bits := buildStream([][]byte{d}, tc.il, 77, tc.inv, tc.flips, r)
		got := CCSDSDeframe(bits, len(d), tc.il, false, 2)
		if len(got) != 1 || !bytes.Equal(got[0].Data, d) || got[0].Inverted != tc.inv {
			t.Fatalf("%+v: frames=%d", tc, len(got))
		}
		if tc.flips > 0 && got[0].Corrected == 0 {
			t.Fatalf("%+v: expected corrections", tc)
		}
	}
	// Pure noise after a false ASM must not yield a frame.
	noise := make([]bool, 3000)
	for i := range noise {
		noise[i] = r.Intn(2) == 1
	}
	copy(noise[100:], bitsOf([]byte{0x1A, 0xCF, 0xFC, 0x1D}))
	if got := CCSDSDeframe(noise, 223, 1, false, 0); len(got) != 0 {
		t.Fatal("noise decoded as frame")
	}
}

// TestRSLibfecVectors checks against codewords produced by Phil Karn's
// libfec (LGPL, github.com/quiet/libfec) encode_rs_8 (conventional basis)
// and encode_rs_ccsds (dual basis): an independent implementation, run
// offline; vectors in testdata/rs_ccsds_libfec_vectors.txt. Still software
// reference vectors, not an over-the-air capture.
func TestRSLibfecVectors(t *testing.T) {
	raw, err := os.ReadFile("testdata/rs_ccsds_libfec_vectors.txt")
	if err != nil {
		t.Fatal(err)
	}
	n := 0
	for _, line := range strings.Split(strings.TrimSpace(string(raw)), "\n") {
		f := strings.Fields(line)
		cw, err := hex.DecodeString(f[1])
		if err != nil || len(cw) != 255 {
			t.Fatalf("bad vector %s", f[0])
		}
		data := append([]byte{}, cw[:223]...)
		if strings.HasPrefix(f[0], "dual") {
			for i := range data {
				data[i] = dualToConv[data[i]]
			}
		}
		got := RSEncode(data)
		if strings.HasPrefix(f[0], "dual") {
			for i := range got {
				got[i] = convToDual[got[i]]
			}
		}
		if !bytes.Equal(got, cw) {
			t.Fatalf("%s: encode mismatch vs libfec", f[0])
		}
		// Decoder: corrupt 9 bytes, must restore libfec's codeword.
		bad := append([]byte{}, cw...)
		for i := 0; i < 9; i++ {
			bad[i*27] ^= 0xA5
		}
		if strings.HasPrefix(f[0], "dual") {
			for i := range bad {
				bad[i] = dualToConv[bad[i]]
			}
		}
		if _, err := RSDecode(bad); err != nil {
			t.Fatalf("%s: %v", f[0], err)
		}
		if strings.HasPrefix(f[0], "dual") {
			for i := range bad {
				bad[i] = convToDual[bad[i]]
			}
		}
		if !bytes.Equal(bad, cw) {
			t.Fatalf("%s: decode mismatch", f[0])
		}
		n++
	}
	if n != 6 {
		t.Fatalf("vectors %d", n)
	}
}

func TestDualBasisInvertible(t *testing.T) {
	for v := 0; v < 256; v++ {
		if dualToConv[convToDual[v]] != byte(v) {
			t.Fatal("not invertible")
		}
	}
}
